exercises.solution:
#include <stdio.h>

static int divide(int a, int b, int *ok) {
    if (b == 0) { *ok = 0; return 0; }
    *ok = 1; return a / b;
}

int main(void) {
    int ok;
    int r = divide(10, 3, &ok);
    printf("%d ", r);
    divide(10, 0, &ok);
    if (!ok) printf("<nil>");
    return 0;
}

exercises.starter_code:
#include <stdio.h>

static int sum(const int *nums, int n) { return 0; }

int main(void) {
    // printf("%d\n", sum(nums, 5));
    return 0;
}

exercises.solution:
#include <stdio.h>

static int sum(const int *nums, int n) {
    int t = 0;
    for (int i = 0; i < n; i++) t += nums[i];
    return t;
}

int main(void) {
    int nums[] = {1, 2, 3, 4, 5};
    printf("%d\n", sum(nums, 5));
    return 0;
}

