int main(void) {
    // process();
    return 0;
}

exercises.solution:
#include <stdio.h>
#include <stdlib.h>

static void print_end(void) { printf("end\n"); }

static void process(void) {
    printf("start\n");
    atexit(print_end);
    printf("working\n");
}

int main(void) { process(); return 0; }

